(function(){
"use strict";

const root=document.getElementById("ilmx-faraid-app");
if(!root)return;

const BASE=24;

const $=id=>document.getElementById(id);

function money(value){
  return new Intl.NumberFormat("ms-MY",{
    style:"currency",
    currency:"MYR",
    minimumFractionDigits:2,
    maximumFractionDigits:2
  }).format(value);
}

function num(id){
  const el=$(id);
  if(!el)return 0;

  const value=parseFloat(el.value);

  return Number.isFinite(value)&&value>0
    ?value
    :0;
}

function clampInt(id){
  const el=$(id);
  if(!el)return 0;

  let value=parseInt(el.value,10)||0;

  const min=parseInt(el.min||"0",10);
  const max=parseInt(el.max||"999",10);

  value=Math.max(min,Math.min(max,value));

  el.value=value;

  return value;
}

function escapeHtml(value){
  return String(value).replace(/[&<>'"]/g,char=>({
    "&":"&amp;",
    "<":"&lt;",
    ">":"&gt;",
    "'":"&#39;",
    '"':"&quot;"
  })[char]);
}

/* =====================================================
   UI
   ===================================================== */

function updateSpouse(){

  const selected=
    root.querySelector(
      'input[name="ilmx-fr-jantina"]:checked'
    );

  if(!selected)return;

  const male=selected.value==="L";

  const input=$("ilmx-fr-pasangan");
  const label=$("ilmx-fr-pasangan-label");

  if(!input||!label)return;

  if(male){

    label.textContent=
      "Bilangan isteri (0–4)";

    input.max="4";

  }else{

    label.textContent=
      "Ada suami? (0 atau 1)";

    input.max="1";

    if(parseInt(input.value,10)>1){
      input.value="1";
    }

  }

}

function changeStepper(button){

  const id=
    button.getAttribute("data-fr-target");

  const input=$(id);

  if(!input)return;

  const delta=
    parseInt(
      button.getAttribute("data-fr-step"),
      10
    )||0;

  const min=
    parseInt(input.min||"0",10);

  const max=
    parseInt(input.max||"999",10);

  const current=
    parseInt(input.value,10)||0;

  input.value=
    Math.max(
      min,
      Math.min(
        max,
        current+delta
      )
    );

  input.dispatchEvent(
    new Event(
      "change",
      {bubbles:true}
    )
  );

}

/* =====================================================
   READ FORM
   ===================================================== */

function readHeirs(){

  const gender=
    root.querySelector(
      'input[name="ilmx-fr-jantina"]:checked'
    );

  return{

    gender:
      gender
        ?gender.value
        :"L",

    spouse:
      clampInt(
        "ilmx-fr-pasangan"
      ),

    father:
      $("ilmx-fr-bapa").checked,

    mother:
      $("ilmx-fr-ibu").checked,

    grandfather:
      $("ilmx-fr-datuk").checked,

    grandmother:
      $("ilmx-fr-nenek").checked,

    sons:
      clampInt(
        "ilmx-fr-anakl"
      ),

    daughters:
      clampInt(
        "ilmx-fr-anakp"
      ),

    brothers:
      clampInt(
        "ilmx-fr-saudl"
      ),

    sisters:
      clampInt(
        "ilmx-fr-saudp"
      )

  };

}

/* =====================================================
   FARAID CORE
   ===================================================== */

function calculateShares(data){

  let used=0;

  const fixed=[];
  const residuary=[];

  const hasChild=
    data.sons>0||
    data.daughters>0;

  const fatherExists=
    data.father;

  const grandfatherExists=
    !fatherExists&&
    data.grandfather;

  const motherExists=
    data.mother;

  const grandmotherExists=
    !motherExists&&
    data.grandmother;

  const rawSiblingCount=
    data.brothers+
    data.sisters;

  /* ---------------------------------------------
     SPOUSE
     --------------------------------------------- */

  if(
    data.gender==="L"&&
    data.spouse>0
  ){

    const share=
      hasChild
        ?BASE/8
        :BASE/4;

    fixed.push({
      label:
        data.spouse>1
          ?`Isteri (${data.spouse} orang, dikongsi)`
          :"Isteri",

      value:share,

      spouse:true
    });

    used+=share;

  }

  if(
    data.gender==="P"&&
    data.spouse>0
  ){

    const share=
      hasChild
        ?BASE/4
        :BASE/2;

    fixed.push({
      label:"Suami",
      value:share,
      spouse:true
    });

    used+=share;

  }

  /* ---------------------------------------------
     GHARRAWAIN
     --------------------------------------------- */

  const gharrawain=
    fatherExists&&
    motherExists&&
    !hasChild&&
    rawSiblingCount===0&&
    data.spouse>0;

  /* ---------------------------------------------
     MOTHER
     --------------------------------------------- */

  if(motherExists){

    const share=
      gharrawain
        ?(BASE-used)/3
        :(
          hasChild||
          rawSiblingCount>=2
            ?BASE/6
            :BASE/3
        );

    fixed.push({
      label:"Ibu",
      value:share
    });

    used+=share;

  }

  /* ---------------------------------------------
     GRANDMOTHER
     --------------------------------------------- */

  if(grandmotherExists){

    const share=BASE/6;

    fixed.push({
      label:"Nenek",
      value:share
    });

    used+=share;

  }

  /* ---------------------------------------------
     FATHER
     --------------------------------------------- */

  if(fatherExists){

    if(hasChild){

      const share=BASE/6;

      fixed.push({
        label:"Bapa",
        value:share
      });

      used+=share;

      if(
        data.sons===0&&
        data.daughters>0
      ){

        residuary.push({
          label:
            "Bapa — baki sebagai asabah",

          weight:1
        });

      }

    }else{

      residuary.push({
        label:"Bapa",
        weight:1
      });

    }

  }

  /* ---------------------------------------------
     GRANDFATHER
     --------------------------------------------- */

  else if(grandfatherExists){

    if(hasChild){

      const share=BASE/6;

      fixed.push({
        label:"Datuk",
        value:share
      });

      used+=share;

      if(
        data.sons===0&&
        data.daughters>0
      ){

        residuary.push({
          label:
            "Datuk — baki sebagai asabah",

          weight:1
        });

      }

    }else{

      residuary.push({
        label:"Datuk",
        weight:1
      });

    }

  }

  /* ---------------------------------------------
     CHILDREN
     --------------------------------------------- */

  if(data.sons>0){

    residuary.push({
      label:
        data.sons>1
          ?`Anak lelaki (${data.sons} orang)`
          :"Anak lelaki",

      weight:
        data.sons*2
    });

    if(data.daughters>0){

      residuary.push({
        label:
          data.daughters>1
            ?`Anak perempuan (${data.daughters} orang)`
            :"Anak perempuan",

        weight:
          data.daughters
      });

    }

  }

  else if(data.daughters>0){

    const share=
      data.daughters===1
        ?BASE/2
        :BASE*2/3;

    fixed.push({
      label:
        data.daughters>1
          ?`Anak perempuan (${data.daughters} orang, dikongsi)`
          :"Anak perempuan",

      value:share
    });

    used+=share;

  }

  /* ---------------------------------------------
     FULL SIBLINGS
     --------------------------------------------- */

  const siblingBlocked=
    fatherExists||
    grandfatherExists||
    data.sons>0;

  const brothers=
    siblingBlocked
      ?0
      :data.brothers;

  const sisters=
    siblingBlocked
      ?0
      :data.sisters;

  if(brothers>0){

    residuary.push({
      label:
        brothers>1
          ?`Saudara lelaki kandung (${brothers} orang)`
          :"Saudara lelaki kandung",

      weight:
        brothers*2
    });

    if(sisters>0){

      residuary.push({
        label:
          sisters>1
            ?`Saudara perempuan kandung (${sisters} orang)`
            :"Saudara perempuan kandung",

        weight:
          sisters
      });

    }

  }

  else if(
    sisters>0&&
    data.daughters>0&&
    data.sons===0
  ){

    residuary.push({
      label:
        sisters>1
          ?`Saudara perempuan kandung (${sisters} orang, asabah ma‘al ghair)`
          :"Saudara perempuan kandung — asabah ma‘al ghair",

      weight:
        sisters
    });

  }

  else if(sisters>0){

    const share=
      sisters===1
        ?BASE/2
        :BASE*2/3;

    fixed.push({
      label:
        sisters>1
          ?`Saudara perempuan kandung (${sisters} orang, dikongsi)`
          :"Saudara perempuan kandung",

      value:share
    });

    used+=share;

  }

  /* ---------------------------------------------
     FINAL DISTRIBUTION
     --------------------------------------------- */

  const result=[];

  let aul=false;
  let radd=false;

  if(used>BASE){

    aul=true;

    const factor=
      BASE/used;

    fixed.forEach(item=>{

      result.push({
        label:item.label,
        portion:
          item.value*factor
      });

    });

    return{
      result,
      aul,
      radd,
      gharrawain
    };

  }

  let remaining=
    BASE-used;

  fixed.forEach(item=>{

    result.push({
      label:item.label,
      portion:item.value,
      spouse:item.spouse||false
    });

  });

  if(
    residuary.length&&
    remaining>0
  ){

    const totalWeight=
      residuary.reduce(
        (sum,item)=>
          sum+item.weight,
        0
      );

    residuary.forEach(item=>{

      result.push({
        label:item.label,
        portion:
          remaining*
          (
            item.weight/
            totalWeight
          )
      });

    });

    remaining=0;

  }

  /* RADD */

  if(
    remaining>0.000001&&
    !residuary.length
  ){

    const eligible=
      result.filter(
        item=>!item.spouse
      );

    const eligibleTotal=
      eligible.reduce(
        (sum,item)=>
          sum+item.portion,
        0
      );

    if(eligibleTotal>0){

      radd=true;

      eligible.forEach(item=>{

        item.portion+=
          remaining*
          (
            item.portion/
            eligibleTotal
          );

      });

      remaining=0;

    }

  }

  if(remaining>0.000001){

    result.push({
      label:
        "Baki — perlu pengesahan pihak berautoriti",

      portion:
        remaining
    });

  }

  return{
    result,
    aul,
    radd,
    gharrawain
  };

}

/* =====================================================
   CALCULATE ESTATE
   ===================================================== */

function calculate(){

  const resultBox=
    $("ilmx-fr-result");

  if(!resultBox)return;

  const estate=
    num(
      "ilmx-fr-estate"
    );

  const funeral=
    num(
      "ilmx-fr-funeral"
    );

  const debts=
    num(
      "ilmx-fr-debts"
    );

  const requestedWasiat=
    num(
      "ilmx-fr-wasiat"
    );

  if(estate<=0){

    resultBox.innerHTML=
      '<div class="ilmx-fr-error">'+
      "Masukkan jumlah harta pusaka terlebih dahulu."+
      "</div>";

    resultBox.classList.add(
      "active"
    );

    return;

  }

  const afterDebts=
    estate-
    funeral-
    debts;

  if(afterDebts<=0){

    resultBox.innerHTML=
      '<div class="ilmx-fr-error">'+
      "Tiada baki harta positif selepas kos jenazah dan hutang."+
      "</div>";

    resultBox.classList.add(
      "active"
    );

    return;

  }

  const maxWasiat=
    afterDebts/3;

  const wasiat=
    Math.min(
      requestedWasiat,
      maxWasiat
    );

  const netEstate=
    afterDebts-
    wasiat;

  const heirs=
    readHeirs();

  const calculation=
    calculateShares(heirs);

  if(!calculation.result.length){

    resultBox.innerHTML=
      '<div class="ilmx-fr-error">'+
      "Masukkan sekurang-kurangnya seorang waris dalam skop kalkulator."+
      "</div>";

    resultBox.classList.add(
      "active"
    );

    return;

  }

  let html="";

  if(requestedWasiat>maxWasiat){

    html+=
      '<div class="ilmx-fr-note">'+
      "Amaun wasiat yang dimasukkan melebihi 1/3. "+
      "Untuk anggaran calculator ini, wasiat dihadkan kepada "+
      money(maxWasiat)+
      "."+
      "</div>";

  }

  if(calculation.gharrawain){

    html+=
      '<div class="ilmx-fr-note">'+
      "Kes gharrawain dikesan dalam kombinasi waris yang dimasukkan."+
      "</div>";

  }

  if(calculation.aul){

    html+=
      '<div class="ilmx-fr-note">'+
      "Aul dikesan dan kadar telah dilaraskan secara berkadar."+
      "</div>";

  }

  if(calculation.radd){

    html+=
      '<div class="ilmx-fr-note">'+
      "Radd dikesan pada baki pusaka dalam skop calculator ini."+
      "</div>";

  }

  html+=
    '<div class="ilmx-fr-result-summary">'+

      '<div class="ilmx-fr-stat">'+
        "<small>Jumlah harta asal</small>"+
        "<strong>"+
          money(estate)+
        "</strong>"+
      "</div>"+

      '<div class="ilmx-fr-stat">'+
        "<small>Selepas kos & hutang</small>"+
        "<strong>"+
          money(afterDebts)+
        "</strong>"+
      "</div>"+

      '<div class="ilmx-fr-stat">'+
        "<small>Wasiat digunakan</small>"+
        "<strong>"+
          money(wasiat)+
        "</strong>"+
      "</div>"+

      '<div class="ilmx-fr-stat">'+
        "<small>Harta bersih untuk faraid</small>"+
        "<strong>"+
          money(netEstate)+
        "</strong>"+
      "</div>"+

    "</div>";


  html+=
    '<div class="ilmx-fr-table-wrap">'+
    '<table class="ilmx-fr-table">'+

      "<thead>"+
        "<tr>"+
          "<th>Waris</th>"+
          "<th>Bahagian</th>"+
          "<th>Anggaran</th>"+
        "</tr>"+
      "</thead>"+

      "<tbody>";


  calculation.result.forEach(item=>{

    const percentage=
      item.portion/
      BASE*
      100;

    const amount=
      netEstate*
      item.portion/
      BASE;

    html+=
      "<tr>"+

        "<td>"+
          escapeHtml(
            item.label
          )+
        "</td>"+

        "<td>"+
          percentage.toFixed(2)+
          "%"+
        "</td>"+

        "<td>"+
          money(amount)+
        "</td>"+

      "</tr>";

  });


  html+=
      "</tbody>"+
    "</table>"+
    "</div>";


  resultBox.innerHTML=html;

  resultBox.classList.add(
    "active"
  );


  if(
    typeof resultBox.focus===
    "function"
  ){

    resultBox.focus({
      preventScroll:true
    });

  }


  resultBox.scrollIntoView({

    behavior:
      window.matchMedia(
        "(prefers-reduced-motion: reduce)"
      ).matches
        ?"auto"
        :"smooth",

    block:"nearest"

  });

}

/* =====================================================
   FAQ
   ===================================================== */

function toggleFaq(button){

  const answer=
    button.nextElementSibling;

  const open=
    button.classList.contains(
      "open"
    );


  root
    .querySelectorAll(
      ".ilmx-fr-faq-q"
    )
    .forEach(item=>{

      item.classList.remove(
        "open"
      );

      item.setAttribute(
        "aria-expanded",
        "false"
      );

    });


  root
    .querySelectorAll(
      ".ilmx-fr-faq-a"
    )
    .forEach(item=>{

      item.classList.remove(
        "open"
      );

    });


  if(!open){

    button.classList.add(
      "open"
    );

    button.setAttribute(
      "aria-expanded",
      "true"
    );

    if(answer){

      answer.classList.add(
        "open"
      );

    }

  }

}

/* =====================================================
   EVENTS
   ===================================================== */

root.addEventListener(
  "click",
  event=>{

    const stepButton=
      event.target.closest(
        "[data-fr-step]"
      );

    if(stepButton){

      changeStepper(
        stepButton
      );

      return;

    }


    const faqButton=
      event.target.closest(
        ".ilmx-fr-faq-q"
      );

    if(faqButton){

      toggleFaq(
        faqButton
      );

      return;

    }


    if(
      event.target.closest(
        "#ilmx-fr-calc-btn"
      )
    ){

      calculate();

    }

  }
);


root.addEventListener(
  "change",
  event=>{

    if(
      event.target.matches(
        'input[name="ilmx-fr-jantina"]'
      )
    ){

      updateSpouse();

    }


    if(
      event.target.matches(
        ".ilmx-fr-step-input"
      )
    ){

      clampInt(
        event.target.id
      );

    }

  }
);


updateSpouse();

})();
